const TEXT_TRANSFORM_SCHEMA = {
  type: 'object',
  properties: {
    text: { type: 'string' },
    mode: { type: 'string', enum: ['uppercase', 'lowercase', 'slug'] },
    trim: { type: 'boolean' }
  },
  required: ['text', 'mode'],
  additionalProperties: false
};

const TOOLS = [
  {
    name: 'text_transform',
    description: 'Transform text. Modes: uppercase, lowercase, slug. Optional trim (default true).',
    inputSchema: TEXT_TRANSFORM_SCHEMA
  }
];

function slugify(value, trim) {
  let s = value;
  if (trim) s = s.trim();
  s = s.toLowerCase();
  s = s.replace(/[^a-z0-9]+/g, '-');
  s = s.replace(/^-+|-+$/g, '');
  return s;
}

function transformText(args) {
  const text = args.text;
  const mode = args.mode;
  const trim = args.trim === undefined ? true : args.trim;

  if (typeof text !== 'string') throw new Error('Invalid arguments: text must be a string');
  if (typeof mode !== 'string') throw new Error('Invalid arguments: mode must be a string');
  if (typeof trim !== 'boolean') throw new Error('Invalid arguments: trim must be a boolean');

  let out;
  switch (mode) {
    case 'uppercase':
      out = trim ? text.trim().toUpperCase() : text.toUpperCase();
      break;
    case 'lowercase':
      out = trim ? text.trim().toLowerCase() : text.toLowerCase();
      break;
    case 'slug':
      out = slugify(text, trim);
      break;
    default:
      throw new Error('Invalid arguments: mode must be one of uppercase, lowercase, slug');
  }
  return { content: [{ type: 'text', text: out }] };
}

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args) {
  if (name !== 'text_transform') throw new Error('Unknown tool: ' + name);
  if (args === null || typeof args !== 'object') throw new Error('Invalid arguments: expected an object');
  return transformText(args);
}

